body.script:
//
  (function () {
    var status = document.getElementById("status");
    function setStatus(msg) { if (status) status.textContent = msg; }

    // Prefer a working Wisp server before the desktop boots (same-origin localStorage
    // does not apply to the CDN iframe — this only helps same-origin embeds).
    try {
      localStorage.setItem(
        "nyx_wisp",
        "wss://wisp.mercurywork.shop/"
      );
    } catch (e) {}

    var mirrors = [
      "https://fastly.jsdelivr.net/gh/Mo9nikeypurple/skool@main/index.html",
      "https://cdn.jsdelivr.net/gh/Mo9nikeypurple/skool@main/index.html",
      "https://gcore.jsdelivr.net/gh/Mo9nikeypurple/skool@main/index.html"
    ];
    var url = mirrors[0] + "?t=" + Date.now();

    var body = document.body
      || document.getElementsByTagName("body")[0]
      || document.documentElement;

    var XHTML = "http://www.w3.org/1999/xhtml";
    var iframe = document.createElementNS(XHTML, "iframe");
    iframe.setAttribute(
      "style",
      "position:absolute;top:0;left:0;width:100%;height:100%;border:none;background:#000;"
    );
    iframe.setAttribute(
      "allow",
      "fullscreen; autoplay; encrypted-media; picture-in-picture; clipboard-read; clipboard-write"
    );
    iframe.setAttribute("referrerpolicy", "no-referrer-when-downgrade");

    var loaded = false;
    iframe.onload = function () {
      loaded = true;
      if (status) status.style.display = "none";
    };
    iframe.onerror = function () {
      setStatus("Failed to load Mac OS. Trying mirror…");
      tryNextMirror(1);
    };

    function tryNextMirror(i) {
      if (i >= mirrors.length) {
        setStatus("Failed to load Mac OS from all mirrors.");
        return;
      }
      setStatus("Loading Mac OS (mirror " + (i + 1) + ")…");
      iframe.setAttribute("src", mirrors[i] + "?t=" + Date.now());
      setTimeout(function () {
        if (!loaded && i + 1 < mirrors.length) tryNextMirror(i + 1);
      }, 12000);
    }

    // Load CDN page directly (no blob) so Apple boot can finish normally
    setStatus("Loading Mac OS…");
    iframe.setAttribute("src", url);
    if (!body) {
      setStatus("No body element found");
      return;
    }
    body.appendChild(iframe);

    // Safety: if still on splash after 25s, show a hint
    setTimeout(function () {
      if (!loaded && status && status.style.display !== "none") {
        setStatus("Still loading… If stuck on the Apple logo, open the page over https:// (not file://) or try a different network.");
      }
    }, 25000);
  })();
//
